// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/policies/policies", wrapper.ListPolicies)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/policies/policies", wrapper.CreatePolicy)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/policies/agents", wrapper.ListAgents)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/policies/policies/{policyId}", wrapper.GetPolicy)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/policies/policies/{policyId}", wrapper.UpdatePolicyTerms)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/policies/policies/{policyId}/accept", wrapper.AcceptPolicy)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/policies/policies/{policyId}/issue", wrapper.IssuePolicy)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/policies/policies/{policyId}/reject", wrapper.RejectPolicy)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/policies/policies/{policyId}/cancel", wrapper.CancelPolicy)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/policies/policies/{policyId}/endorsements", wrapper.RequestEndorsement)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/policies/policies/{policyId}/endorsements/{endorsementId}/issue", wrapper.IssueEndorsement)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/policies/policies/{policyId}/endorsements/{endorsementId}/reject", wrapper.RejectEndorsement)
	})

	return r
}

